class Solution {
  private static long countLength(int len, int[] bound) {
    int off = 9 * len + 1, size = 2 * off + 1;
    long[][] ways = new long[len + 1][size];
    ways[len][off] = 1;
    for (int pos = len - 1; pos >= 0; pos--) {
      int sign = pos % 2 == 0 ? 1 : -1;
      for (int d = 0; d < size; d++) {
        long w = 0;
        for (int digit = 0; digit <= 9; digit++) {
          int nd = d + sign * digit;
          if (nd >= 0 && nd < size) w += ways[pos + 1][nd];
        }
        ways[pos][d] = w;
      }
    }
    long total = 0;
    if (bound == null) {
      for (int digit = 1; digit <= 9; digit++) total += ways[1][off + digit];
      return total;
    }
    int diff = 0;
    for (int pos = 0; pos < len; pos++) {
      int sign = pos % 2 == 0 ? 1 : -1;
      for (int digit = pos == 0 ? 1 : 0; digit < bound[pos]; digit++)
        total += ways[pos + 1][off + diff + sign * digit];
      diff += sign * bound[pos];
    }
    if (diff == 0) total++;
    return total;
  }

  private static long upTo(long n) {
    if (n < 10) return 0;
    String s = Long.toString(n);
    int L = s.length();
    long total = 0;
    for (int len = 2; len < L; len++) total += countLength(len, null);
    int[] bound = new int[L];
    for (int i = 0; i < L; i++) bound[i] = s.charAt(i) - '0';
    return total + countLength(L, bound);
  }

  public long countBalanced(long low, long high) {
    return upTo(high) - upTo(low - 1);
  }
}
